{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C01","C05","C08","C09","C12","C18","C24","C30","C31","C49","C84",
    "C140","C143","C146","C149","C170","C187","C189","C194","C195","C197","C218","C222",
    "C259","C269","C270","C271","C273","C280","C285"
  ],
  "contradictory_card_ids": ["C35","C39","C86"],
  "prediction_basis_card_ids": [
    "C01","C05","C09","C12","C18","C24","C30","C31","C49","C84",
    "C140","C143","C170","C187","C189","C195","C222",
    "C259","C273","C280"
  ],
  "claims": [
    {
      "claim": "Transferable L1 gold contexts consistently report absolute oral bioavailability at or above 20% in humans: apixaban ~50% (C01, C08), pentopril >58–70% (C05, C12, C30, C31), cefroxadine ~100% (C09, C49, C84), and midodrine 93% (C18, C24).",
      "card_ids": ["C01","C05","C08","C09","C12","C18","C24","C30","C31","C49","C84"]
    },
    {
      "claim": "L4/L5 intestinal absorption and permeability records for related lipophilic basic amines show high absorption and no significant efflux: imipramine essentially 100% absorbed with Caco-2 ER 1.1 (C140, C143, C170, C187, C189), promethazine passive ER 1.1 (C149, C195), nicardipine high passive permeability with efflux insignificant (C146, C194, C197), and compound 16a Papp A-B 19.9e-6 with ER 0.7 (C222).",
      "card_ids": ["C140","C143","C146","C149","C170","C187","C189","C194","C195","C197","C222"]
    },
    {
      "claim": "L6 hepatic metabolism records for reference molecules do not provide affirmative low-F evidence; tamoxifen is extensively CYP3A4-metabolized (C259, C273, C280) yet its L1 F is ~100% (C03, C04, C07), and imipramine has measurable HLM CLint (C269, C270, C271, C285) but essentially complete absorption (C140, C143, C170, C187).",
      "card_ids": ["C259","C273","C280","C03","C04","C07","C269","C270","C271","C285","C140","C143","C170","C187"]
    },
    {
      "claim": "The only sub-20% records are species-specific and non-transferable to the human-condition query: tamoxifen 13.15% in horses (C35, C86) and ASV 11% in monkeys (C39); they do not support low F for the query.",
      "card_ids": ["C35","C39","C86"]
    },
    {
      "claim": "No query-specific hepatic clearance or metabolic-stability record is present; C287 (eslicarbazepine acetate ester hydrolysis in HLM) is for a different reference molecule and cannot by itself establish low F for the query's acetate ester.",
      "card_ids": ["C287"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C259","C269","C270","C271","C273","C280","C285","C287"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No query-specific hepatic clearance or metabolic-stability record is present; L6 records are for reference molecules.",
    "No matched oral-versus-IV exposure data are available for the query.",
    "First-pass ester hydrolysis and any P-gp/CYP3A contribution for the query are not directly quantified.",
    "Transfer from animal/species-specific low-F records is limited."
  ],
  "decision_summary": "For this benzothiazepine with a tertiary amine and acetate ester, transferable L1 gold contexts consistently support F>=20%, and L4/L5 intestinal absorption/permeability and efflux records for related lipophilic basic amines support high absorption and no significant efflux. L6 hepatic metabolism records for reference molecules show that measurable CYP-mediated clearance does not by itself establish F<20%; no query-specific low-F evidence was added. Prediction remains high and is strengthened."
}

